#include <Servo.h>
#include <DHT.h>

const byte DHT_PIN = 2;
const byte DHT_TYPE = DHT11;
const byte TRIG_PIN = 4;
const byte ECHO_PIN = 3;
const byte SERVO_PIN = 9;
const float TEMP_OPEN_C = 30.0;
const float HUMIDITY_OPEN_PERCENT = 70.0;
const float NEAR_DISTANCE_CM = 20.0;
const byte CLOSED_ANGLE = 0;
const byte OPEN_ANGLE = 90;

DHT climateSensor(DHT_PIN, DHT_TYPE);
Servo ventServo;

float readDistanceCm() {
  digitalWrite(TRIG_PIN, LOW);
  delayMicroseconds(2);
  digitalWrite(TRIG_PIN, HIGH);
  delayMicroseconds(10);
  digitalWrite(TRIG_PIN, LOW);
  const unsigned long duration = pulseIn(ECHO_PIN, HIGH, 30000UL);
  if (duration == 0) return -1.0;  // No echo / out of range
  return duration * 0.0343 / 2.0;
}

void setup() {
  Serial.begin(9600);
  climateSensor.begin();
  pinMode(TRIG_PIN, OUTPUT);
  pinMode(ECHO_PIN, INPUT);
  digitalWrite(TRIG_PIN, LOW);
  ventServo.attach(SERVO_PIN);
  ventServo.write(CLOSED_ANGLE);
  delay(1000);
}

void loop() {
  const float humidity = climateSensor.readHumidity();
  const float temperatureC = climateSensor.readTemperature();
  const float distanceCm = readDistanceCm();

  if (isnan(humidity) || isnan(temperatureC)) {
    ventServo.write(CLOSED_ANGLE);
    Serial.println("DHT11 read failed; vent closed");
    delay(2000);
    return;
  }

  const bool climateNeedsVent =
      (temperatureC >= TEMP_OPEN_C) || (humidity >= HUMIDITY_OPEN_PERCENT);
  const bool someoneNear = (distanceCm > 0.0 && distanceCm <= NEAR_DISTANCE_CM);
  const bool ventOpen = climateNeedsVent || someoneNear;
  ventServo.write(ventOpen ? OPEN_ANGLE : CLOSED_ANGLE);

  Serial.print("Temperature: ");
  Serial.print(temperatureC);
  Serial.print(" C | humidity: ");
  Serial.print(humidity);
  Serial.print(" % | distance: ");
  Serial.print(distanceCm);
  Serial.print(" cm | vent: ");
  Serial.println(ventOpen ? "OPEN" : "CLOSED");

  delay(2000);
}
